-- Sprint 3 (S3-09): baseline schema, exported from the JPA entities on 31 Oct 2026.
-- New databases are built from this file. Existing databases (created earlier by ddl-auto=update)
-- are adopted at version 1 by spring.flyway.baseline-on-migrate and do not run it.

create table asset_classes (created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, name varchar(255), primary key (id));
create table bank_accounts (current_balance numeric(38,2), opening_balance numeric(38,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, account_holder_name varchar(255), account_number varchar(255), account_type varchar(255), bank_name varchar(255), iban varchar(255), name varchar(255), primary key (id));
create table bank_transactions (amount numeric(38,2) not null, created_at timestamp(6), transaction_date timestamp(6), updated_at timestamp(6), bank_account_id uuid not null, id uuid not null, reference_id uuid not null, tenant_id uuid not null, user_id uuid, description varchar(255), reference_type varchar(255) not null check (reference_type in ('LOAN_EMI','CHIT_INSTALLMENT','RECURRING_DEPOSIT','SIP_INVESTMENT','INSURANCE_PREMIUM','UTILITY_BILL','MANUAL_ENTRY','SYSTEM_CORRECTION')), type varchar(255) not null check (type in ('DEBIT','CREDIT')), primary key (id));
create table budgets (amount numeric(38,2) not null, email_alert boolean not null, rollover boolean not null, month varchar(7) not null, created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, category varchar(255) not null, primary key (id));
create table chit_funds (allotted_amount numeric(38,2), duration_months integer, is_allotted boolean, monthly_installment numeric(38,2), pending_installments integer, start_date date, total_value numeric(38,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, linked_bank_account_id uuid, tenant_id uuid not null, user_id uuid, member_name varchar(255), organizer_name varchar(255), payment_schedule TEXT, primary key (id));
create table commitments (active boolean not null, amount numeric(38,2), due_day integer, end_date date, interval_months integer, start_date date, created_at timestamp(6), updated_at timestamp(6), id uuid not null, linked_chit_fund_id uuid, linked_loan_id uuid, tenant_id uuid not null, user_id uuid, commitment_group varchar(20) not null check (commitment_group in ('INCOME','MUST_PAY','LIVING','PAUSABLE')), frequency varchar(20) not null check (frequency in ('MONTHLY','DAILY','EVERY_N_MONTHS')), notes varchar(500), category varchar(255), name varchar(255) not null, primary key (id));
create table credit_cards (billing_cycle_date integer, credit_limit numeric(38,2), due_date integer, opening_outstanding numeric(38,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, bank_name varchar(255), card_holder_name varchar(255), card_name varchar(255), card_number varchar(255), primary key (id));
create table deposits (interest_rate float(53), maturity_amount numeric(38,2), maturity_date date, monthly_deposit_amount numeric(38,2), principal_amount numeric(38,2), start_date date, total_deposited numeric(38,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, linked_bank_account_id uuid, tenant_id uuid not null, user_id uuid, account_holder_name varchar(255), institution varchar(255), type varchar(255), primary key (id));
create table document_versions (version_number integer not null, created_at timestamp(6), size bigint not null, updated_at timestamp(6), document_id uuid not null, id uuid not null, uploaded_by uuid not null, file_path varchar(255) not null, primary key (id));
create table documents (expiry_date date, created_at timestamp(6), size bigint not null, updated_at timestamp(6), associated_entity_id uuid, id uuid not null, tenant_id uuid not null, uploaded_by uuid not null, user_id uuid, associated_entity_type varchar(255), category varchar(255) not null, description text, file_path varchar(255) not null, name varchar(255) not null, type varchar(255) not null, extracted_data jsonb, tags jsonb, primary key (id));
create table expenses (amount numeric(38,2) not null, expense_date date not null, loan_interest_portion numeric(15,2), loan_principal_portion numeric(15,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, linked_bank_account_id uuid, linked_chit_fund_id uuid, linked_credit_card_id uuid, linked_deposit_id uuid, linked_income_source_id uuid, linked_investment_id uuid, linked_loan_id uuid, linked_peer_lending_id uuid, linked_project_id uuid, tenant_id uuid not null, user_id uuid, kind varchar(20) check (kind in ('INCOME','EXPENSE','INVESTMENT','LOAN_PAYMENT','LENDING','TRANSFER')), type varchar(20), made_against varchar(50), description varchar(500), category varchar(255) not null, custom_fields_data TEXT, edit_history TEXT, primary key (id));
create table goals (current_amount numeric(38,2) not null, target_amount numeric(38,2) not null, target_date date not null, created_at timestamp(6), updated_at timestamp(6), id uuid not null, linked_bank_account_id uuid, tenant_id uuid not null, user_id uuid, category varchar(255), name varchar(255) not null, priority varchar(255) not null, primary key (id));
create table income_sources (amount numeric(38,2), date_received date, created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, frequency varchar(255), owner_name varchar(255), source_name varchar(255), primary key (id));
create table investments (current_value numeric(38,2), invested_amount numeric(38,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, name varchar(255), owner_name varchar(255), type varchar(255), primary key (id));
create table loans (emi_amount numeric(38,2), interest_rate float(53), outstanding_amount numeric(38,2), principal_amount numeric(38,2), remaining_tenure integer, created_at timestamp(6), updated_at timestamp(6), id uuid not null, linked_bank_account_id uuid, tenant_id uuid not null, user_id uuid, interest_method varchar(20), borrower_name varchar(255), lender_name varchar(255), loan_type varchar(255), primary key (id));
create table notifications (is_read boolean not null, created_at timestamp(6), updated_at timestamp(6), document_id uuid, id uuid not null, tenant_id uuid not null, user_id uuid, message varchar(255) not null, primary key (id));
create table peer_lendings (amount numeric(38,2), date date, expected_return_date date, principal_amount numeric(15,2), repaid_amount numeric(15,2), settled boolean, created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, owner_name varchar(255), person_name varchar(255), type varchar(255), primary key (id));
create table physical_document_logs (created_at timestamp(6), updated_at timestamp(6), document_id uuid not null, id uuid not null, performed_by uuid not null, tenant_id uuid not null, user_id uuid, action_type varchar(255) not null, borrower_name varchar(255), notes text, primary key (id));
create table physical_locations (is_original_present boolean not null, created_at timestamp(6), last_borrowed_at timestamp(6), updated_at timestamp(6), document_id uuid not null unique, id uuid not null, tenant_id uuid not null, user_id uuid, almirah_id varchar(255) not null, folder varchar(255), holder varchar(255), last_borrowed_by varchar(255), shelf varchar(255), slot varchar(255), sub_folder varchar(255), primary key (id));
create table project_expenses (amount numeric(38,2), date date, created_at timestamp(6), updated_at timestamp(6), expense_id uuid, id uuid not null, project_id uuid, tenant_id uuid not null, user_id uuid, category varchar(255), description varchar(255), primary key (id));
create table projects (budget numeric(38,2), end_date date, start_date date, created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, user_id uuid, custom_fields_config TEXT, name varchar(255), priority varchar(255), status varchar(255), primary key (id));
create table scheduled_payments (amount numeric(38,2) not null, due_date date not null, created_at timestamp(6), updated_at timestamp(6), bank_account_id uuid not null, id uuid not null, reference_id uuid not null, tenant_id uuid not null, user_id uuid, description varchar(500), failure_reason varchar(500), reference_type varchar(255) not null check (reference_type in ('LOAN_EMI','CHIT_INSTALLMENT','RECURRING_DEPOSIT','SIP_INVESTMENT','INSURANCE_PREMIUM','UTILITY_BILL','MANUAL_ENTRY','SYSTEM_CORRECTION')), status varchar(255) not null check (status in ('PENDING','PROCESSED','FAILED','CANCELLED')), transaction_type varchar(255) not null check (transaction_type in ('DEBIT','CREDIT')), primary key (id));
create table tenants (created_at timestamp(6), updated_at timestamp(6), id uuid not null, address text, avatar_url varchar(255), name varchar(255) not null, phone varchar(255), plan varchar(255) not null, primary key (id));
create table users (created_at timestamp(6), updated_at timestamp(6), id uuid not null, tenant_id uuid not null, email varchar(255) not null unique, name varchar(255) not null, password_hash varchar(255), phone varchar(255), role varchar(255) not null, primary key (id));
